def results():
    return pd.DataFrame(DATA)
def render():
    st.subheader("Gerçek bankacılık verisi | 9 kontrol senaryosu")
    st.caption("26.11.2026 — Kaydedilmiş doğrulanmış deney; 36 yöntem-senaryo sonucu, canlı tarama değildir.")
    st.warning("Referans etiketleri tanımlı kurallardan türetilmiştir; gerçek ihlal veya dolandırıcılık etiketi değildir. Yaş tek başına risk kanıtı değildir. Pozitif kayıt olmayan senaryolarda recall tanımsızdır.")
    d=results()
    ref=d[d.method=="algorithmic_reference"][["scenario","n","reference_positive"]]
    st.dataframe(ref,hide_index=True)
    selected=st.selectbox("Kontrol senaryosu",list(ref.scenario),key="verified_control_scenario")
    subset=d[d.scenario==selected].copy()
    st.dataframe(subset,hide_index=True)
    if subset.reference_positive.iloc[0]>0:
        st.bar_chart(subset.set_index("method")[["precision","recall","f1"]])
    else:st.info("Bu senaryoda pozitif referans kaydı yoktur; tespit başarısı ölçülemez.")
    st.download_button("Tüm kontrol sonuçları CSV",d.to_csv(index=False).encode("utf-8-sig"),"banking_controls_verified.csv","text/csv")
    st.markdown("[Deney kaydı]("+RUN+") · [Sonuç arşivi]("+RUN+"/artifacts/15106273316)")
    st.caption("Yetki limiti, teminat, onay kayıtları, KYC/MASAK ve sözleşmesel kullandırım şartları gerekli alanlar bulunmadığından test edilmemiştir.")
